using FailedOverride.Units; using FailedOverride.Campaign;
namespace FailedOverride.Battle;
public enum Phase { Player, Enemy, Victory, Defeat }
public sealed class BattleState {
 public readonly string[] Map; public MissionDefinition Definition {get;} public int Mission {get;} public Cell Shuttle=>Definition.Shuttle??new(10,1);
 public List<Unit> Units {get;}=[]; public List<string> Log {get;}=[]; public CampaignState Campaign {get;}
 public Phase Phase {get;private set;}=Phase.Player; public int Round {get;private set;}=1; public Cell Console=>Definition.Console??new(6,4); public bool ConsoleUsed {get;private set;} private int robotId; readonly Dictionary<string,Cell> moveOrigins=[];readonly Dictionary<string,IReadOnlyList<Cell>> movePaths=[];public IReadOnlyList<Cell> LastMovePath {get;private set;}=[];public Cell Bridge=>Definition.Bridge??new(9,1);public int BridgeProgress {get;private set;}public string DefeatReason {get;private set;}="";public Cell? Noise {get;private set;}public HashSet<Cell> UsedTraps {get;}=[];
 public Unit Issac=>Units.Single(u=>u.Role==Role.Officer); public int Robots=>Units.Count(u=>u.Alive&&u.Role==Role.Robot); public bool Finished=>Phase is Phase.Victory or Phase.Defeat;
 public BattleState(int mission=1,CampaignState? campaign=null){ Mission=mission; Campaign=campaign??new(); Definition=MissionDefinition.For(mission); Map=Definition.UnitRows;
 int d=0; for(int y=0;y<12;y++)for(int x=0;x<12;x++){ Unit? u=Map[y][x] switch {
  'X'=>Make("xander","Xander McRaven","X",Role.Scout,Team.Player,18,1,6),'N'=>Make("nance","Nance Parker","N",Role.Shapeshifter,Team.Player,20,1,5),
  'A'=>Make("akiko","Akiko Ikeda","A",Role.Tech,Team.Player,16,1,5),'I'=>Make("issac","Issac Wynter","I",Role.Officer,mission==1?Team.Civilian:Team.Player,18,0,mission==1?0:4),
  'D'=>Make($"droid-{++d}",$"Corrupted droid {d}","D",Role.Droid,Team.Enemy,16,2,3),'H'=>Make("heavy-droid","Corrupted heavy droid","H",Role.HeavyDroid,Team.Enemy,26,4,2),'o'=>Make("otto","Otto","O",Role.Twin,Team.Player,12,0,5),'e'=>Make("odette","Odette","O",Role.Twin,Team.Player,12,0,5),'T'=>Make("tiger","Tiger","T",Role.Dog,Team.Player,14,0,6),'C'=>mission==3?Make("chrandy","Dr. Chrandy Perra","C",Role.Medic,Team.Player,17,1,5):null,'M'=>Make("ompok-proxy","Ompok proxy","M",Role.OmpokProxy,Team.Enemy,36,4,3),'V'=>Make("vaur","Vaur brute","V",Role.VaurBrute,Team.Enemy,22,3,3),'K'=>Make("khelt","Khelt stalker","K",Role.KheltStalker,Team.Enemy,14,1,5),'Y'=>Make("engineer","Synaptic engineer","Y",Role.SynapticEngineer,Team.Enemy,16,2,4),_=>null}; if(u!=null){u.Position=new(x,y);if(u.Role==Role.Medic)u.MedicalSupplies=3;u.Hidden=mission==3&&u.Role is Role.KheltStalker or Role.SynapticEngineer;Units.Add(u);} } Campaign.Apply(Units);if(mission>=2){var x=Units.Single(u=>u.Role==Role.Scout);var n=Units.Single(u=>u.Role==Role.Shapeshifter);var a=Units.Single(u=>u.Role==Role.Tech);var i=Units.Single(u=>u.Role==Role.Officer);if(Campaign.XanderUpgrade=="Marksman")x.Level++;else if(Campaign.XanderUpgrade=="Skirmisher")x.BaseMove++;if(Campaign.NanceUpgrade=="Iron Bear")n.BaseArmor++;else if(Campaign.NanceUpgrade=="Enduring Bear")n.BaseHp+=4;if(Campaign.AkikoUpgrade=="Field Tech")a.BaseHp+=4;if(Campaign.IssacUpgrade=="Combat Training")i.Level++;if(mission==2)Note("Escort Issac to the shuttle. Damage a droid below half HP to reprogram it.");}if(mission==3){Note("Ompok followed the shuttle aboard. Stop his proxy before it takes the bridge.");Reveal();}else if(mission==1)Note("Reach Issac and use Rescue from an adjacent tile."); }
 static Unit Make(string id,string name,string token,Role role,Team team,int hp,int armor,int move)=>new(){Id=id,Name=name,Token=token,Role=role,Team=team,BaseHp=hp,Hp=hp,BaseArmor=armor,BaseMove=move};
 public void Note(string s){Log.Add(s);if(Log.Count>30)Log.RemoveAt(0);} public TerrainCell TerrainAt(Cell c)=>Definition.At(c); public bool Floor(Cell c)=>TerrainAt(c).Walkable; public Unit? At(Cell c)=>Units.FirstOrDefault(u=>u.Alive&&u.Position==c);
 public bool Command(Unit u)=>Phase==Phase.Player&&u.Alive&&!u.Captured&&u.Team==Team.Player;public bool Enter(Unit u,Cell c)=>Floor(c)&&(Map[c.Y][c.X]!='v'||u.Small);
 public int MovementCost(Cell from,Cell to)=>TerrainAt(from).Elevation==0&&TerrainAt(to).Elevation==1?3:1;
 (Dictionary<Cell,int> costs,Dictionary<Cell,Cell> previous) Search(Unit u,int budget){
  Dictionary<Cell,int> costs=new(){{u.Position,0}};Dictionary<Cell,Cell> previous=[];PriorityQueue<Cell,int> open=new();open.Enqueue(u.Position,0);
  while(open.TryDequeue(out var c,out var queued)){if(queued!=costs[c]||queued>=budget)continue;foreach(var n in c.Neighbors()){
   if(!Enter(u,n)||(At(n)!=null&&n!=u.Position))continue;int next=queued+MovementCost(c,n);if(next>budget||costs.TryGetValue(n,out var old)&&old<=next)continue;
   costs[n]=next;previous[n]=c;open.Enqueue(n,next);
  }}return(costs,previous);
 }
 public Dictionary<Cell,int> Reach(Unit u)=>Search(u,u.Move).costs;
 IReadOnlyList<Cell> PathWithBudget(Unit u,Cell destination,int budget){var search=Search(u,budget);if(!search.costs.ContainsKey(destination))return[];List<Cell> path=[destination];while(path[^1]!=u.Position)path.Add(search.previous[path[^1]]);path.Reverse();return path;}
 public IReadOnlyList<Cell> Path(Unit u,Cell destination)=>PathWithBudget(u,destination,u.Move);
 public bool Move(Unit u,Cell c){if(!Command(u)||u.Moved||c==u.Position||!Reach(u).ContainsKey(c))return false;LastMovePath=Path(u,c);movePaths[u.Id]=LastMovePath;moveOrigins[u.Id]=u.Position;u.Position=c;u.Moved=true;if(u.Role==Role.Dog){Reveal();if(Units.Any(x=>!x.Captured&&x.Role==Role.Twin&&x.Position.Distance(u.Position)==1)){Noise=null;Note("A twin calms Tiger down.");}else if(Noise!=null)Noise=u.Position;}Note($"{u.Name} moved.");return true;}
 public bool UndoMove(Unit u){if(!Command(u)||!u.Moved||u.Acted||!moveOrigins.TryGetValue(u.Id,out var origin)||At(origin)!=null)return false;LastMovePath=movePaths.TryGetValue(u.Id,out var original)?original.Reverse().ToList():PathWithBudget(u,origin,144);u.Position=origin;u.Moved=false;moveOrigins.Remove(u.Id);movePaths.Remove(u.Id);Note($"{u.Name} canceled the move.");return true;}
 public IReadOnlyList<Cell> Trace(Cell a,Cell b){int dx=b.X-a.X,dy=b.Y-a.Y,n=Math.Max(Math.Abs(dx),Math.Abs(dy));List<Cell> cells=[];for(int i=1;i<n;i++){var c=new Cell((int)Math.Round(a.X+dx*(double)i/n),(int)Math.Round(a.Y+dy*(double)i/n));if(!cells.Contains(c))cells.Add(c);}return cells;}
 public bool Los(Cell a,Cell b)=>Trace(a,b).All(c=>!TerrainAt(c).BlocksSight);
 public bool HasLowCover(Cell a,Cell b)=>Trace(a,b).Any(c=>TerrainAt(c).Kind==TerrainKind.LowCover);
 public bool Range(Unit a,Cell c,Weapon w)=>a.Position.Distance(c)>0&&a.Position.Distance(c)<=w.Range&&Los(a.Position,c);
 public int BondBonus(Unit u)=>Units.Any(x=>x.Alive&&x.Team==Team.Player&&x!=u&&x.Position.Distance(u.Position)==1&&Campaign.Bond(u.Id,x.Id)>0)?1:0;
 DamageBreakdown PreviewDamageFrom(Unit a,Unit t,Weapon w,Cell from){if(w.StunOnly)return new(0,0,0,0);bool ranged=w.Range>1;int high=ranged&&TerrainAt(from).Elevation>TerrainAt(t.Position).Elevation?2:0;int uphill=ranged&&TerrainAt(from).Elevation<TerrainAt(t.Position).Elevation?1:0;int cover=ranged&&HasLowCover(from,t.Position)?1:0;int damage=Math.Max(1,w.Power+a.Level-1+BondBonus(a)-t.Armor-BondBonus(t)+high-uphill-cover);return new(damage,high,uphill,cover);}
 public DamageBreakdown PreviewDamageBreakdown(Unit a,Unit t,Weapon w)=>PreviewDamageFrom(a,t,w,a.Position);
 public int PreviewDamage(Unit a,Unit t,Weapon w)=>PreviewDamageBreakdown(a,t,w).FinalDamage;
 void Hit(Unit a,Unit t,Weapon w){if(t.Role is Role.Twin or Role.Dog){t.Captured=true;t.Acted=t.Moved=true;Note($"{a.Name} captured {t.Name}!");return;}var breakdown=PreviewDamageBreakdown(a,t,w);int damage=breakdown.FinalDamage;t.Hp=Math.Max(0,t.Hp-damage);if(w.Stun&&t.Alive&&t.Role!=Role.OmpokProxy)t.Stunned=1;var terrain=breakdown.ModifierSummary.Length>0?$" ({breakdown.ModifierSummary})":"";Note($"{a.Name}: {w.Name} → {t.Name}, {damage} damage{terrain}{(w.Stun&&t.Alive?" + stun":"")}.");if(!t.Alive)Note($"{t.Name} defeated.");if(a.Hero){a.Xp+=t.Alive?25:50;if(a.Xp>=100){a.Xp-=100;a.Level++;Note($"{a.Name} reached level {a.Level}!");}}}
 public bool Attack(Unit a,Unit t,int i){if(!Command(a)||a.Acted||i<0||i>=a.Weapons.Count||a.Weapons[i].StunOnly&&t.Role==Role.OmpokProxy||!t.Alive||t.Team==a.Team||t.Team==Team.Civilian||!Range(a,t.Position,a.Weapons[i]))return false;Hit(a,t,a.Weapons[i]);a.Acted=true;Evaluate();return true;}
 public bool Transform(Unit u){if(!Command(u)||u.Acted||u.Role!=Role.Shapeshifter)return false;if(u.Bear&&u.Hp<=6){Note("Nance needs more than 6 HP to leave Bear form.");return false;}u.Bear=!u.Bear;u.Hp+=u.Bear?6:-6;u.Acted=true;Note($"Nance shifted to {(u.Bear?"Bear":"human")} form.");return true;}
 public IEnumerable<Cell> SummonCells(Unit u)=>u.Position.Neighbors().Where(c=>Floor(c)&&At(c)==null);
 public bool Summon(Unit u,Cell c){if(!Command(u)||u.Acted||u.Role!=Role.Tech||Robots>=3||!SummonCells(u).Contains(c))return false;var r=Make($"robot-{++robotId}",$"Support robot {robotId}","R",Role.Robot,Team.Player,10,1,4);r.Position=c;if(Campaign.AkikoUpgrade=="Hardened Robots")r.BaseArmor++;r.Acted=r.Moved=true;Units.Add(r);u.Acted=true;Note("Akiko deployed a robot.");return true;}
 public bool Reprogram(Unit u,Unit d){if(!Command(u)||u.Acted||u.Role!=Role.Officer||d.Team!=Team.Enemy||d.Role is not (Role.Droid or Role.HeavyDroid)||d.Hp*2>d.MaxHp||u.Position.Distance(d.Position)!=1)return false;d.Team=Team.Player;d.Acted=d.Moved=true;u.Acted=true;Note($"Issac reprogrammed {d.Name}. It joins next round.");return true;}
 public bool Heal(Unit medic,Unit target){if(!Command(medic)||medic.Acted||medic.Role!=Role.Medic||medic.MedicalSupplies<=0||target==medic||!target.Alive||target.Team!=Team.Player||target.Role is Role.Robot or Role.Droid or Role.HeavyDroid or Role.OmpokProxy||target.Hp>=target.MaxHp||medic.Position.Distance(target.Position)!=1)return false;int amount=Math.Min(7,target.MaxHp-target.Hp);target.Hp+=amount;medic.MedicalSupplies--;medic.Acted=true;Note($"Chrandy treats {target.Name} for {amount} HP ({medic.MedicalSupplies} supplies remain).");return true;}
 public bool Repair(Unit u,Unit target){if(!Command(u)||u.Acted||u.Role is not (Role.Tech or Role.Officer)||target.Team!=Team.Player||target.Role is not (Role.Robot or Role.Droid or Role.HeavyDroid)||!target.Alive||target.Hp>=target.MaxHp||u.Position.Distance(target.Position)!=1)return false;int power=Campaign.IssacUpgrade=="Master Mechanic"&&u.Role==Role.Officer?9:6;int amount=Math.Min(power,target.MaxHp-target.Hp);target.Hp+=amount;u.Acted=true;Note($"{u.Name} repaired {target.Name} for {amount} HP.");return true;}
 public bool RushTiger(Unit tiger,bool towardTwin){if(!Command(tiger)||tiger.Acted||tiger.Role!=Role.Dog)return false;Unit? target=towardTwin?Units.Where(x=>x.Alive&&!x.Captured&&x.Role==Role.Twin).OrderBy(x=>x.Position.Distance(tiger.Position)).FirstOrDefault():Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(tiger.Position)).FirstOrDefault();if(target==null)return false;moveOrigins[tiger.Id]=tiger.Position;tiger.Position=Reach(tiger).Keys.OrderBy(c=>c.Distance(target.Position)).First();tiger.Moved=tiger.Acted=true;Reveal();Note(towardTwin?"Tiger runs back toward the twins.":"Tiger barks and rushes toward the enemy!");Noise=tiger.Position;return true;}
 public void Reveal(){var tiger=Units.FirstOrDefault(x=>x.Alive&&!x.Captured&&x.Role==Role.Dog);if(tiger==null)return;foreach(var enemy in Units.Where(x=>x.Alive&&x.Hidden&&x.Position.Distance(tiger.Position)<=3)){enemy.Hidden=false;Note($"Tiger spotted {enemy.Name}!");}}
 public bool TriggerTrap(Unit u){if(!Command(u)||u.Acted||u.Role!=Role.Twin||!u.Position.Neighbors().Any(c=>Floor(c)&&Map[c.Y][c.X]=='v'))return false;var target=Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(u.Position)).FirstOrDefault();if(target==null)return false;target.Hp=Math.Max(0,target.Hp-6);target.Stunned=1;u.Acted=true;Note($"{u.Name} springs a trap: {target.Name} takes 6 damage and is stunned.");Evaluate();return true;}
 public bool RescueCaptive(Unit u){if(!Command(u)||u.Acted||!u.Hero)return false;var captive=Units.FirstOrDefault(x=>x.Alive&&x.Captured&&x.Position.Distance(u.Position)==1);if(captive==null)return false;captive.Captured=false;captive.Acted=captive.Moved=true;u.Acted=true;Note($"{u.Name} rescued {captive.Name}.");return true;}
 public bool Interact(Unit u){if(!Command(u)||u.Acted)return false;if(Mission==3&&u.Role==Role.Twin)return TriggerTrap(u);if(Mission==2&&u.Role==Role.Officer&&u.Position.Distance(Shuttle)<=1){Phase=Phase.Victory;Campaign.CompletedMissions.Add("mission-2");Campaign.Record(Units);Campaign.GrowBonds(Units.Where(x=>x.Alive&&(x.Hero||x.Role==Role.Officer)).Select(x=>x.Id));Note("Issac reached the evacuation shuttle!");return true;}if(!u.Hero)return false;if(u.Position.Distance(Issac.Position)==1&&Issac.Alive){Phase=Phase.Victory;Campaign.CompletedMissions.Add("failed-override");Campaign.Record(Units);Campaign.GrowBonds(Units.Where(x=>x.Alive&&x.Hero).Select(x=>x.Id));Note("Issac rescued. Mission complete!");return true;}if(!ConsoleUsed&&u.Position.Distance(Console)<=1){var d=Units.Where(x=>x.Alive&&x.Team==Team.Enemy).OrderBy(x=>x.Position.Distance(Console)).FirstOrDefault();if(d==null)return false;d.Stunned=1;ConsoleUsed=true;u.Acted=true;Note($"Console disabled {d.Name} for one turn.");return true;}return false;}
 public void Wait(Unit u){if(Command(u)){u.Acted=u.Moved=true;Note($"{u.Name} waits.");}}
 public void StartEnemy(){if(Phase==Phase.Player){Phase=Phase.Enemy;Note("Enemy phase.");}}
 void AdvanceTowardObjective(Unit unit,Cell objective){
  var route=objective.Neighbors().Where(c=>TerrainAt(c).Walkable&&(At(c)==null||c==unit.Position)).Select(c=>PathWithBudget(unit,c,144)).Where(p=>p.Count>0).OrderBy(p=>p.Zip(p.Skip(1),(a,b)=>MovementCost(a,b)).Sum()).FirstOrDefault();
  if(route==null){LastMovePath=[unit.Position];return;}int spent=0,index=0;for(int i=1;i<route.Count;i++){int step=MovementCost(route[i-1],route[i]);if(spent+step>unit.Move)break;spent+=step;index=i;}LastMovePath=route.Take(index+1).ToList();unit.Position=route[index];
 }
 public void Enemy(Unit e){if(Phase!=Phase.Enemy||!e.Alive)return;LastMovePath=[e.Position];e.Hidden=false;if(e.Stunned>0){e.Stunned--;Note($"{e.Name} is stunned.");return;}if(e.Role==Role.OmpokProxy){if(e.Position.Distance(Bridge)<=1){BridgeProgress++;Note($"Ompok links to the bridge ({BridgeProgress}/2)!");if(BridgeProgress>=2){DefeatReason="Ompok completed the bridge takeover.";Phase=Phase.Defeat;Note(DefeatReason);}return;}AdvanceTowardObjective(e,Bridge);Note("Ompok advances toward the bridge.");return;}var targets=Units.Where(u=>u.Alive&&!u.Captured&&u.Team==Team.Player).OrderByDescending(u=>Noise!=null&&u.Role==Role.Dog).ToList();if(Round>=6)targets.Add(Issac);var option=(from c in Reach(e) from t in targets from w in e.Weapons where c.Key.Distance(t.Position)>0&&c.Key.Distance(t.Position)<=w.Range&&Los(c.Key,t.Position) orderby (Noise!=null&&t.Role==Role.Dog?0:1),t.Team==Team.Civilian,PreviewDamageFrom(e,t,w,c.Key).FinalDamage descending,c.Value select(c:c.Key,t,w)).FirstOrDefault();if(option.t!=null){LastMovePath=Path(e,option.c);e.Position=option.c;Hit(e,option.t,option.w);}else{var target=targets.OrderBy(t=>t.Position.Distance(e.Position)).First();var advanceDestination=Reach(e).Keys.OrderBy(c=>c.Distance(target.Position)).First();LastMovePath=Path(e,advanceDestination);e.Position=advanceDestination;Note($"{e.Name} advances.");}Evaluate();}
 public void StartPlayer(){if(Phase!=Phase.Enemy)return;Round++;Phase=Phase.Player;moveOrigins.Clear();foreach(var u in Units.Where(u=>u.Alive&&u.Team==Team.Player)){u.SkippedByStun=u.Stunned>0;u.Moved=u.Acted=u.SkippedByStun;if(u.Stunned>0){u.Stunned--;Note($"{u.Name} is stunned this phase.");}}Noise=null;Note($"Player phase · round {Round}.");}
 public void Evaluate(){if(Finished)return;if(Mission==3&&!Units.Any(x=>x.Alive&&x.Team==Team.Enemy)){Phase=Phase.Victory;Campaign.CompletedMissions.Add("mission-3");Campaign.Record(Units);Note("Ompok’s proxy force is defeated!");return;}bool defeated=Mission switch {1=>!Issac.Alive||!Units.Any(u=>u.Alive&&u.Hero),2=>!Issac.Alive||!Units.Any(u=>u.Alive&&u.Hero),3=>!Units.Any(u=>u.Alive&&(u.Hero||u.Role==Role.Officer)),_=>false};if(defeated){DefeatReason=Mission==3?"Every combat-capable crew member was defeated.":!Issac.Alive?"Issac was killed.":"All three heroes were defeated.";Phase=Phase.Defeat;Note(DefeatReason);}}
}
